function MenuView({ menu, activeCategory, setActiveCategory, expandedItem, setExpandedItem, addToCart }) {
  const items = menu.filter((m) => m.category === activeCategory);
  const canAddOns = activeCategory !== "sides" && activeCategory !== "drinks";

  return (
    <section className="sb-menu">
      <div className="sb-menu-tabs">
        {CATEGORIES.map((c) => {
          const Icon = c.icon;
          return (
            <button
              key={c.id}
              className={`sb-tab ${activeCategory === c.id ? "active" : ""}`}
              onClick={() => { setActiveCategory(c.id); setExpandedItem(null); }}
            >
              <Icon size={15} /> {c.label}
            </button>
          );
        })}
      </div>

      <div className="sb-menu-grid">
        {items.map((item) => (
          <MenuItemCard
            key={item.id}
            item={item}
            canAddOns={canAddOns}
            expanded={expandedItem === item.id}
            onExpand={() => setExpandedItem(expandedItem === item.id ? null : item.id)}
            onAdd={addToCart}
          />
        ))}
      </div>
    </section>
  );
}

function MenuItemCard({ item, canAddOns, expanded, onExpand, onAdd }) {
  const [qty, setQty] = useState(1);
  const [selectedAddons, setSelectedAddons] = useState([]);
  const hasSizes = Boolean(item.sizes);
  const availableSizes = hasSizes ? item.sizes.filter((s) => !s.soldOut) : null;
  const allSizesSoldOut = hasSizes && availableSizes.length === 0;
  const [selectedSize, setSelectedSize] = useState(
    hasSizes ? availableSizes[0] || item.sizes[0] : null
  );

  // If the menu updates (e.g. an admin marks the currently-selected size sold
  // out) while a customer has this card open, fall back to another available
  // size rather than leaving a now-invalid selection picked.
  useEffect(() => {
    if (!hasSizes) return;
    const stillValid = item.sizes.some((s) => s.label === selectedSize?.label && !s.soldOut);
    if (!stillValid) {
      setSelectedSize(item.sizes.find((s) => !s.soldOut) || item.sizes[0]);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [item.sizes]);

  const isSoldOut = item.soldOut || allSizesSoldOut;

  const toggleAddon = (addon) => {
    setSelectedAddons((s) =>
      s.some((a) => a.name === addon.name) ? s.filter((a) => a.name !== addon.name) : [...s, addon]
    );
  };

  const unitPrice = hasSizes ? selectedSize.price : item.price;
  const runningTotal = (unitPrice + selectedAddons.reduce((s, a) => s + a.price, 0)) * qty;
  const sizesForPricing = hasSizes ? (availableSizes.length > 0 ? availableSizes : item.sizes) : null;
  const displayPrice = hasSizes
    ? `From ${money(Math.min(...sizesForPricing.map((s) => s.price)))}`
    : money(item.price);

  return (
    <div className={`sb-card ${isSoldOut ? "sb-card-soldout" : ""}`}>
      <div className="sb-card-top">
        <div>
          <h3 className="sb-card-name">{item.name}</h3>
          <p className="sb-card-desc">{item.desc}</p>
        </div>
        <span className="sb-card-price">{displayPrice}</span>
      </div>

      {isSoldOut ? (
        <div className="sb-soldout-tag">Sold out today</div>
      ) : !expanded ? (
        <button className="sb-btn-outline-sm" onClick={onExpand}>
          <Plus size={14} /> Add
        </button>
      ) : (
        <div className="sb-card-expand">
          {hasSizes && (
            <div className="sb-addons">
              <span className="sb-addons-label">Choose size</span>
              <div className="sb-addons-list">
                {item.sizes.map((s) => (
                  <label
                    key={s.label}
                    className={`sb-size-chip ${selectedSize?.label === s.label ? "active" : ""} ${s.soldOut ? "sb-size-chip-disabled" : ""}`}
                  >
                    <input
                      type="radio"
                      name={`size-${item.id}`}
                      checked={selectedSize?.label === s.label}
                      disabled={s.soldOut}
                      onChange={() => !s.soldOut && setSelectedSize(s)}
                    />
                    {s.label}{" "}
                    <span className="sb-addon-price">{s.soldOut ? "Sold out" : money(s.price)}</span>
                  </label>
                ))}
              </div>
            </div>
          )}
          {canAddOns && (
            <div className="sb-addons">
              <span className="sb-addons-label">Add a side</span>
              <div className="sb-addons-list">
                {ADDONS.map((a) => (
                  <label key={a.name} className="sb-addon-chip">
                    <input
                      type="checkbox"
                      checked={selectedAddons.some((s) => s.name === a.name)}
                      onChange={() => toggleAddon(a)}
                    />
                    {a.name} <span className="sb-addon-price">+{money(a.price)}</span>
                  </label>
                ))}
              </div>
            </div>
          )}
          <div className="sb-qty-row">
            <div className="sb-stepper">
              <button onClick={() => setQty((q) => Math.max(1, q - 1))}><Minus size={14} /></button>
              <span>{qty}</span>
              <button onClick={() => setQty((q) => q + 1)}><Plus size={14} /></button>
            </div>
            <button
              className="sb-btn-gold-sm"
              onClick={() => { onAdd(item, selectedAddons, qty, hasSizes ? selectedSize : null); setQty(1); setSelectedAddons([]); }}
            >
              Add &middot; {money(runningTotal)}
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

